object DialogHub {
  final case class Checked(value: Boolean)              // the protocol
  def apply(): Behavior[Checked] =
    Behaviors.setup { ctx =>
      Behaviors.receiveMessage { msg =>
        emailField.tell(Enable(!msg.value), ctx.self)  // route to a colleague
        Behaviors.same
      }
    }
}
val hub: ActorRef[Checked] = ctx.spawn(DialogHub(), "dialog")
hub ! Checked(true)
